    73→func (s *Service) ReceiveBlock(ctx context.Context, block interfaces.ReadOnlySignedBeaconBlock, blockRoot [32]byte, avs das.AvailabilityStore) error {
    74→	ctx, span := trace.StartSpan(ctx, "blockChain.ReceiveBlock")
    75→	defer span.End()
    76→	// Return early if the block is blacklisted
    77→	if features.BlacklistedBlock(blockRoot) {
    78→		return errBlacklistedRoot
    79→	}
    80→	// Return early if the block has been synced
    81→	if s.InForkchoice(blockRoot) {
    82→		log.WithField("blockRoot", fmt.Sprintf("%#x", blockRoot)).Debug("Ignoring already synced block")
    83→		return nil
    84→	}
    85→
    86→	receivedTime := time.Now()
    87→	err := s.blockBeingSynced.set(blockRoot)
    88→	if errors.Is(err, errBlockBeingSynced) {
    89→		log.WithField("blockRoot", fmt.Sprintf("%#x", blockRoot)).Debug("Ignoring block currently being synced")
    90→		return nil
    91→	}
    92→	defer s.blockBeingSynced.unset(blockRoot)
    93→
    94→	blockCopy, err := block.Copy()
    95→	if err != nil {
    96→		return err
    97→	}
    98→
    99→	preState, err := s.getBlockPreState(ctx, blockCopy.Block())
   100→	if err != nil {
   101→		return errors.Wrap(err, "could not get block's prestate")
   102→	}
   103→
   104→	currentCheckpoints := s.saveCurrentCheckpoints(preState)
   105→	roblock, err := blocks.NewROBlockWithRoot(blockCopy, blockRoot)
   106→	if err != nil {
   107→		return err
   108→	}
   109→
   110→	postState, isValidPayload, err := s.validateExecutionAndConsensus(ctx, preState, roblock)
   111→	if err != nil {
   112→		return err
   113→	}
   114→
   115→	daWaitedTime, err := s.handleDA(ctx, blockCopy, blockRoot, avs)
   116→	if err != nil {
   117→		return err
   118→	}
   119→
   120→	// Defragment the state before continuing block processing.
   121→	s.defragmentState(postState)
   122→
   123→	// The rest of block processing takes a lock on forkchoice.
   124→	s.cfg.ForkChoiceStore.Lock()
   125→	defer s.cfg.ForkChoiceStore.Unlock()
   126→	if err := s.savePostStateInfo(ctx, blockRoot, blockCopy, postState); err != nil {
   127→		return errors.Wrap(err, "could not save post state info")
   128→	}
   129→	args := &postBlockProcessConfig{
   130→		ctx:            ctx,
   131→		roblock:        roblock,
   132→		postState:      postState,
   133→		isValidPayload: isValidPayload,
   134→	}
   135→	if err := s.postBlockProcess(args); err != nil {
   136→		err := errors.Wrap(err, "could not process block")
   137→		tracing.AnnotateError(span, err)
   138→		return err
   139→	}
   140→	if err := s.updateCheckpoints(ctx, currentCheckpoints, preState, postState, blockRoot); err != nil {
   141→		return err
   142→	}
   143→	// If slasher is configured, forward the attestations in the block via an event feed for processing.
   144→	if s.slasherEnabled {
   145→		go s.sendBlockAttestationsToSlasher(blockCopy, preState)
